CREATE OR REPLACE FUNCTION public.set_unit_status(unit_id uuid,new_status public.unit_leasing_status,reason text,ref_type text,ref_id uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u public.units;b public.bookings;c public.contracts;legacy public.unit_contracts;r text;actor uuid:=auth.uid();ar text;before_row jsonb;first_id uuid;first_due numeric;first_ex numeric;first_vat numeric;paid_ex numeric;paid_vat numeric; BEGIN
IF new_status IS NULL OR nullif(btrim(ref_type),'') IS NULL THEN RAISE EXCEPTION 'الحالة ونوع المرجع مطلوبان'; END IF;r:=public._assert_reason(reason);
SELECT * INTO u FROM public.units WHERE id=unit_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'الوحدة غير موجودة'; END IF;
SELECT role::text INTO ar FROM public.user_roles WHERE user_id=actor AND is_active ORDER BY CASE WHEN role='leasing_manager' THEN 0 WHEN role='admin' THEN 1 ELSE 2 END LIMIT 1;
IF public.has_role(actor,'manager') AND NOT(public.has_role(actor,'admin') OR public.has_role(actor,'leasing_manager')) THEN RAISE EXCEPTION 'صلاحية المدير للعرض فقط'; END IF;
IF new_status='leased' THEN IF NOT public.has_role(actor,'leasing_manager') OR ref_type<>'contract' THEN RAISE EXCEPTION 'التأجير يتطلب تأكيدًا يدويًا من مدير التأجير'; END IF;
ELSIF public.has_role(actor,'control') AND NOT public.has_role(actor,'admin') THEN IF NOT((u.leasing_status='available' AND new_status='maintenance') OR(u.leasing_status='maintenance' AND new_status='available')) OR ref_type<>'maintenance' THEN RAISE EXCEPTION 'صلاحية التحكم للصيانة فقط'; END IF;
ELSIF NOT public.has_role(actor,'admin') THEN IF ref_type NOT IN('booking','booking_cancel','booking_expiry') THEN RAISE EXCEPTION 'غير مصرح بتغيير حالة الوحدة'; END IF; END IF;
IF ref_type IN('booking','booking_confirm','booking_cancel','booking_expiry','booking_unit_cancel') THEN SELECT * INTO b FROM public.bookings WHERE id=ref_id;IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.booking_units bu WHERE bu.booking_id=b.id AND bu.unit_id=u.id) THEN RAISE EXCEPTION 'مرجع الحجز لا يخص الوحدة'; END IF;IF NOT public.has_role(actor,'admin') AND NOT((b.user_id=actor AND ref_type IN('booking','booking_cancel')) OR(ref_type='booking_expiry' AND(auth.role()='service_role' OR(actor IS NULL AND session_user='postgres')))) THEN RAISE EXCEPTION 'غير مصرح بإدارة هذا الحجز'; END IF; END IF;
IF NOT u.leasing_status_initialized OR u.leasing_status IS NULL THEN RAISE EXCEPTION 'حالة الوحدة غير محسومة؛ راجع سجل المراجعة'; END IF;
IF NOT((u.leasing_status='available' AND new_status IN('on_hold','maintenance','blocked')) OR(u.leasing_status='on_hold' AND new_status IN('pending_contract','available')) OR(u.leasing_status='pending_contract' AND new_status IN('leased','available')) OR(u.leasing_status IN('leased','maintenance','blocked') AND new_status='available')) THEN RAISE EXCEPTION 'انتقال حالة الوحدة غير مسموح: % ← %',u.leasing_status,new_status; END IF;
IF new_status='on_hold' AND(ref_type<>'booking' OR b.status<>'pending' OR b.expires_at<=now() OR b.archived_at IS NOT NULL) THEN RAISE EXCEPTION 'الحجز المؤقت يتطلب طلب حجز صالح'; END IF;
IF new_status='pending_contract' AND(ref_type<>'booking_confirm' OR b.status<>'confirmed' OR b.archived_at IS NOT NULL) THEN RAISE EXCEPTION 'انتظار العقد يتطلب تأكيد الحجز'; END IF;
IF new_status='available' AND u.leasing_status IN('on_hold','pending_contract') THEN IF NOT((ref_type='booking_cancel' AND b.status='cancelled') OR(ref_type='booking_expiry' AND b.status='expired' AND u.leasing_status='on_hold') OR(ref_type='booking_unit_cancel' AND EXISTS(SELECT 1 FROM public.booking_units bu WHERE bu.booking_id=b.id AND bu.unit_id=u.id AND bu.archived_at IS NOT NULL))) THEN RAISE EXCEPTION 'تحرير الوحدة يتطلب إلغاء أو انتهاء موثق'; END IF; END IF;
IF new_status='leased' THEN SELECT * INTO c FROM public.contracts WHERE id=ref_id FOR UPDATE;IF NOT FOUND OR c.status<>'active' OR c.needs_review OR c.start_date>current_date OR c.end_date<current_date OR NOT EXISTS(SELECT 1 FROM public.contract_units cu WHERE cu.contract_id=c.id AND cu.unit_id=u.id) THEN RAISE EXCEPTION 'عقد فعال موثق يخص الوحدة مطلوب'; END IF;
SELECT id,amount_excl_vat,vat_amount,amount_incl_vat INTO first_id,first_ex,first_vat,first_due FROM public.installments WHERE contract_id=c.id AND sequence_no=1 FOR UPDATE;IF first_id IS NULL OR first_due<=0 THEN RAISE EXCEPTION 'القسط الأول غير موجود'; END IF;
SELECT coalesce(sum(a.amount_excl_vat),0),coalesce(sum(a.vat_amount),0) INTO paid_ex,paid_vat FROM public.receipt_allocations a JOIN public.receipts x ON x.id=a.receipt_id WHERE a.installment_id=first_id AND x.status='verified' AND x.reverses_id IS NULL AND x.archived_at IS NULL AND x.party_id=c.party_id AND x.contract_id=c.id;
IF paid_ex<first_ex OR paid_vat<first_vat THEN RAISE EXCEPTION 'القسط الأول غير مغطى بالكامل بإيصالات متحققة'; END IF;
ELSIF new_status='available' AND u.leasing_status='leased' THEN IF ref_type<>'contract' THEN RAISE EXCEPTION 'مرجع عقد الوحدة مطلوب'; END IF;SELECT * INTO c FROM public.contracts WHERE id=ref_id;IF FOUND THEN IF c.status NOT IN('ended','terminated') OR NOT EXISTS(SELECT 1 FROM public.contract_units cu WHERE cu.contract_id=c.id AND cu.unit_id=u.id) THEN RAISE EXCEPTION 'انتهاء أو إنهاء عقد الوحدة مطلوب'; END IF;ELSE SELECT * INTO legacy FROM public.unit_contracts WHERE id=ref_id AND unit_contracts.unit_id=u.id;IF NOT FOUND OR legacy.status NOT IN('ended','terminated') THEN RAISE EXCEPTION 'لا يمكن تحرير وحدة مؤجرة قبل انتهاء أو إنهاء عقدها'; END IF;END IF;END IF;
IF new_status IN('available','on_hold') THEN IF EXISTS(SELECT 1 FROM public.tenants t WHERE t.unit_id=u.id AND t.archived_at IS NULL) OR EXISTS(SELECT 1 FROM public.unit_contracts ct WHERE ct.unit_id=u.id AND ct.status='active') OR EXISTS(SELECT 1 FROM public.contract_units cu JOIN public.contracts ct ON ct.id=cu.contract_id WHERE cu.unit_id=u.id AND ct.status='active') OR EXISTS(SELECT 1 FROM public.booking_units bu JOIN public.bookings ob ON ob.id=bu.booking_id WHERE bu.unit_id=u.id AND bu.archived_at IS NULL AND ob.archived_at IS NULL AND ob.status IN('pending','confirmed') AND(new_status='available' OR ob.id IS DISTINCT FROM b.id)) THEN RAISE EXCEPTION 'الوحدة مرتبطة بإشغال أو حجز آخر؛ لا يمكن إتاحتها أو حجزها'; END IF;END IF;
before_row:=to_jsonb(u);INSERT INTO public.unit_status_write_capabilities VALUES(txid_current(),u.id) ON CONFLICT DO NOTHING;UPDATE public.units SET leasing_status=new_status,updated_at=now() WHERE id=u.id;
INSERT INTO public.unit_status_history(unit_id,from_status,to_status,actor,actor_role,reason,ref_type,ref_id) VALUES(u.id,u.leasing_status,new_status,actor,coalesce(ar,'system'),r,ref_type,ref_id);
INSERT INTO public.audit_log(actor_id,actor_role,action,entity_table,entity_id,before_data,after_data,context) VALUES(actor,coalesce(ar,'system'),'UNIT_STATUS_TRANSITION','units',u.id::text,before_row,(SELECT to_jsonb(z) FROM public.units z WHERE z.id=u.id),jsonb_build_object('reason',r,'ref_type',ref_type,'ref_id',ref_id));END $$;
CREATE OR REPLACE FUNCTION public.set_contract_state(_id uuid,_status text,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.contracts; BEGIN PERFORM public.finance_assert_writer();PERFORM public._assert_reason(_reason); SELECT * INTO c FROM public.contracts WHERE id=_id FOR UPDATE;IF NOT FOUND OR NOT((c.status='draft' AND _status='cancelled') OR(c.status='active' AND _status IN('ended','terminated'))) THEN RAISE EXCEPTION 'انتقال العقد غير مسموح'; END IF;IF _status='ended' AND c.end_date>=current_date THEN RAISE EXCEPTION 'لم تنته مدة العقد بعد'; END IF;UPDATE public.contracts SET status=_status,updated_at=now(),reason=_reason WHERE id=c.id;PERFORM public.finance_audit('CONTRACT_STATE','contracts',c.id,to_jsonb(c),(SELECT to_jsonb(x) FROM public.contracts x WHERE id=c.id),_reason);END $$;
REVOKE ALL ON FUNCTION public.set_contract_state(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_contract_state(uuid,text,text) TO authenticated;
SELECT pg_get_functiondef('public.set_unit_status(uuid,public.unit_leasing_status,text,text,uuid)'::regprocedure) LIKE '%القسط الأول غير مغطى%' AS first_installment_gate;